-- PostgreSQL 16 reference schema. SQLAlchemy models in backend/app/models.py are canonical for this MVP.
CREATE TABLE users (id BIGSERIAL PRIMARY KEY, email VARCHAR(255) UNIQUE NOT NULL, display_name VARCHAR(160) NOT NULL, role VARCHAR(40) NOT NULL DEFAULT 'ANALYST', is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE accounts (id BIGSERIAL PRIMARY KEY, account_code VARCHAR(80) UNIQUE NOT NULL, account_name VARCHAR(200), base_currency CHAR(3) NOT NULL DEFAULT 'USD', is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE securities (id BIGSERIAL PRIMARY KEY, security_code VARCHAR(80) UNIQUE NOT NULL, description VARCHAR(250), isin VARCHAR(12), cusip VARCHAR(9), asset_type VARCHAR(50));
CREATE TABLE source_files (id BIGSERIAL PRIMARY KEY, filename VARCHAR(255) NOT NULL, source_side VARCHAR(20) NOT NULL CHECK (source_side IN ('CUSTODIAN','INTERNAL')), record_type VARCHAR(20) NOT NULL, sha256 CHAR(64) NOT NULL, row_count INTEGER NOT NULL, uploaded_at TIMESTAMPTZ NOT NULL DEFAULT now(), uploaded_by BIGINT REFERENCES users(id));
CREATE TABLE reconciliation_runs (id BIGSERIAL PRIMARY KEY, record_type VARCHAR(20) NOT NULL, business_date DATE NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'COMPLETED', config JSONB NOT NULL, total_count INTEGER NOT NULL DEFAULT 0, matched_count INTEGER NOT NULL DEFAULT 0, break_count INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE transaction_records (id BIGSERIAL PRIMARY KEY, source_file_id BIGINT NOT NULL REFERENCES source_files(id), side VARCHAR(20) NOT NULL, account_code VARCHAR(80) NOT NULL, transaction_id VARCHAR(120) NOT NULL, security_code VARCHAR(80) NOT NULL, transaction_type VARCHAR(30), trade_date DATE, settlement_date DATE, quantity NUMERIC(24,8), price NUMERIC(24,8), net_amount NUMERIC(24,8), currency CHAR(3) NOT NULL, raw_data JSONB NOT NULL);
CREATE INDEX ix_txn_match ON transaction_records(side, account_code, transaction_id, security_code);
CREATE TABLE position_snapshots (id BIGSERIAL PRIMARY KEY, source_file_id BIGINT NOT NULL REFERENCES source_files(id), side VARCHAR(20) NOT NULL, business_date DATE NOT NULL, account_code VARCHAR(80) NOT NULL, security_code VARCHAR(80) NOT NULL, currency CHAR(3) NOT NULL, quantity NUMERIC(24,8), price NUMERIC(24,8), market_value NUMERIC(24,8), raw_data JSONB NOT NULL);
CREATE INDEX ix_position_match ON position_snapshots(business_date, side, account_code, security_code, currency);
CREATE TABLE reconciliation_results (id BIGSERIAL PRIMARY KEY, run_id BIGINT NOT NULL REFERENCES reconciliation_runs(id) ON DELETE CASCADE, record_type VARCHAR(20) NOT NULL, match_key VARCHAR(500) NOT NULL, account_code VARCHAR(80), security_code VARCHAR(80), status VARCHAR(20) NOT NULL, break_types JSONB NOT NULL, result_data JSONB NOT NULL);
CREATE INDEX ix_result_run_status ON reconciliation_results(run_id,status);
CREATE TABLE reconciliation_breaks (id BIGSERIAL PRIMARY KEY, run_id BIGINT NOT NULL REFERENCES reconciliation_runs(id), record_type VARCHAR(20) NOT NULL, match_key VARCHAR(500) NOT NULL, account_code VARCHAR(80), security_code VARCHAR(80), break_types JSONB NOT NULL, difference_data JSONB NOT NULL, root_cause VARCHAR(100) NOT NULL DEFAULT 'Pending investigation', owner VARCHAR(160), status VARCHAR(30) NOT NULL DEFAULT 'OPEN', comment TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX ix_break_run_status ON reconciliation_breaks(run_id,status);
CREATE TABLE break_comments (id BIGSERIAL PRIMARY KEY, break_id BIGINT NOT NULL REFERENCES reconciliation_breaks(id) ON DELETE CASCADE, user_id BIGINT REFERENCES users(id), comment TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_events (id BIGSERIAL PRIMARY KEY, user_id BIGINT REFERENCES users(id), entity_type VARCHAR(60) NOT NULL, entity_id VARCHAR(80) NOT NULL, action VARCHAR(60) NOT NULL, before_data JSONB, after_data JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
